      "signatureWeaponId": "23048",
      "signatureWeaponName": "Epoch Etched in Golden Blood",
      "overviewArt": "../../Database/Nanoka/hsr/assets/lightcones/full/23048.webp",
      "overviewArtPool": [
        "../../Database/Nanoka/hsr/assets/lightcones/full/23048.webp"
      ],
      "status": "live",
      "labels": [],
      "r": 5,
