      "signatureWeaponId": "23043",
      "signatureWeaponName": "Lies Dance on the Breeze",
      "overviewArt": "../../Database/Nanoka/hsr/assets/lightcones/full/23043.webp",
      "overviewArtPool": [
        "../../Database/Nanoka/hsr/assets/lightcones/full/23043.webp"
      ],
      "status": "live",
      "labels": [],
      "r": 5,
