      "signatureWeaponId": "23037",
      "signatureWeaponName": "Into the Unreachable Veil",
      "overviewArt": "../../Database/Nanoka/hsr/assets/lightcones/full/23037.webp",
      "overviewArtPool": [
        "../../Database/Nanoka/hsr/assets/lightcones/full/23037.webp"
      ],
      "status": "live",
      "labels": [],
      "r": 5,
